export default class Upload {
    icon;
    name;
    label;
    description;
    #storage;
    publicPath;
    listed;
    documentLabel;
    permissions;
    constructor(options) {
        this.icon = options.icon || "images-square-fill";
        this.name = options.name;
        this.label = options.label || options.name;
        this.description = options.description;
        this.#storage = options.storage;
        this.publicPath = options.publicPath ?? "/";
        this.listed = options.listed ?? true;
        this.documentLabel = options.documentLabel;
        this.permissions = {
            edit: options.edit ?? true,
            create: options.create ?? true,
            delete: options.delete ?? true,
            rename: options.rename ?? true,
        };
    }
    async *[Symbol.asyncIterator]() {
        for await (const source of this.#storage) {
            yield getMetadata(source, this.documentLabel);
        }
    }
    get(id) {
        return this.#storage.get(id);
    }
    async delete(id) {
        await this.#storage.delete(id);
    }
    async rename(id, newId) {
        const newName = this.#storage.name(newId);
        await this.#storage.rename(id, newName);
    }
}
function getMetadata(source, labelizer) {
    if (labelizer) {
        const label = labelizer(source.name);
        if (typeof label === "string") {
            return {
                ...source,
                label,
            };
        }
        return {
            ...source,
            ...label,
        };
    }
    return {
        ...source,
        label: source.name,
    };
}
